<script setup lang="ts">
import {ref,watch} from 'vue'
import HomeDateRange from './HomeDateRange.vue'
import HomeCompositionChart from './HomeCompositionChart.vue'
import {useBusinessDay,financials,homeMoney as money,homePercent as percent,homeColors as colors,type HomeRange} from './homeFinancials'
const day=useBusinessDay()
const props=defineProps<{store:string,market:string,currency:string,refresh:number}>()
const boxes=ref<any[]>([
 {id:'today',title:'今日',period:'today',range:{period:'today'},data:null,busy:false,error:'',seq:0},
 {id:'history',title:'历史统计',period:'yesterday',range:{period:'yesterday'},data:null,busy:false,error:'',seq:0},
 {id:'income',title:'收入构成',period:'7',range:{period:'7'},data:null,busy:false,error:'',seq:0},
 {id:'expense',title:'支出构成',period:'7',range:{period:'7'},data:null,busy:false,error:'',seq:0}])
const metrics=[
 ['estimated_profit','订单预估利润','按所选日期内下单的订单，使用订单页预估利润汇总；费用尚未齐全时显示已估算部分。'],
 ['estimated_margin','订单预估利润率','订单预估利润 ÷ 同期订单销售额。销售额缺失或不大于0时不计算。'],
 ['settlement_profit','结算利润','所选入账日期内已释放的销售交易净额 − 广告费 − 仓储费；费用取结算流水，冲回按原符号计入。退款损益在订单毛利润计入。'],
 ['settlement_margin','结算利润率','结算利润 ÷ 同期下单的订单销售额。'],
 ['gross_profit','订单毛利润','结算利润 − 已释放销售对应的商品成本 − 物流已结算头程总价 ＋ 退款订单损益。头程按所选北京时间内、对应店铺及目的国的已结算物流总价汇总；退款不重复扣商品预估头程。商品成本未维护按0；退款待核实部分暂按已退回可售，原回款缺失暂不加回，后续同步重算。'],
 ['gross_margin','订单毛利率','订单毛利润 ÷ 同期下单的订单销售额。']]
async function load(box:any,force=false){const id=++box.seq;box.busy=true;box.error='';box.data=null;try{const data=await financials(props.store,props.market,props.currency,box.range,force);if(id===box.seq)box.data=data}catch(e){if(id===box.seq)box.error=(e as Error).message}finally{if(id===box.seq)box.busy=false}}
function change(box:any,range:HomeRange){box.range=range;void load(box)}
function details(box:any){const s=box.data?.summary;if(!s)return '';return `快捷日期按北京时间切换；下单按站点当地日期，结算按当地入账日期。${s.orders}笔订单；${s.unknown_estimates}笔预估利润待补齐；${s.unknown_sales}笔销售额待补齐；${s.estimated_refunds||0}笔退款暂按已退回可售估算；${s.unknown_refunds}笔退款金额待补齐；${s.estimated_costs}笔成本含0估算。`}

watch(()=>[props.store,props.market,props.currency,props.refresh],(value,old)=>boxes.value.forEach(b=>void load(b,!!old&&value[3]!==old[3])),{immediate:true})
watch(day,()=>boxes.value.filter(b=>b.range.period!=='custom').forEach(b=>void load(b)))
</script>
<template><div class="home-financial-cards"><article v-for="box in boxes" :key="box.id" class="panel financial-card" :aria-busy="box.busy"><header><h2>{{box.title}}</h2><HomeDateRange v-if="box.id!=='today'" v-model="box.period" compact include-fortnight :include-yesterday="box.id==='history'" :start="box.data?.start" :end="box.data?.end" @change="r=>change(box,r)"/></header><el-alert v-if="box.error" :title="box.error" type="error" :closable="false"/><div v-loading="box.busy" class="financial-body"><template v-if="box.id==='today'||box.id==='history'"><div class="primary-metrics"><div title="所选日期内订单商品数量，排除取消订单"><span>销量</span><strong>{{box.data?.summary.units?.toLocaleString('zh-CN')??'—'}}<small>件</small></strong></div><div :title="details(box)"><span>销售额</span><strong>{{money(box.data?.summary.sales,currency)}}</strong></div></div><div class="profit-grid"><div v-for="[key,label,help] in metrics" :key="key"><el-tooltip :content="help+' '+details(box)" placement="top" :show-after="200"><span tabindex="0">{{label}}</span></el-tooltip><strong :class="{negative:Number(box.data?.summary[key!])<0}">{{key!.endsWith('margin')?percent(box.data?.summary[key!]):money(box.data?.summary[key!],currency)}}<small v-if="key!.startsWith('gross_')&&box.data?.summary.estimated_refunds" class="estimate-mark">*</small></strong></div></div></template><template v-else><HomeCompositionChart :rows="box.data?.composition[box.id]?.rows||[]" :total="box.data?.composition[box.id]?.total??null" :currency="currency" :label="box.id==='income'?'总收入':'总支出'"/><div class="composition-table"><table><thead><tr><th>项目</th><th>金额</th><th>占比</th></tr></thead><tbody><tr v-for="(row,i) in box.data?.composition[box.id]?.rows||[]" :key="row.label"><td><i :style="{background:colors[Number(i)%colors.length]}"/>{{row.label}}</td><td>{{money(row.amount,currency)}}</td><td>{{percent(row.percent)}}</td></tr></tbody></table><el-empty v-if="box.data&&!box.data.composition[box.id].rows.length" description="此日期范围暂无收支明细" :image-size="35"/></div></template></div><el-tooltip v-if="box.data" :content="box.id==='today'||box.id==='history'?details(box):`快捷日期按北京时间切换。根据已释放结算流水及对应商品成本汇总；头程取所选北京时间内对应店铺、目的国的物流已结算总价，暂缓及资金划转不计入。表格保留正负号，占比以净合计为分母；圆环按绝对金额展示构成。${box.data.composition_unknown}项金额待补齐；${box.data.excluded_transfers}笔资金划转或预留金已排除。`"><span class="range-caption" tabindex="0">{{box.data.start}} — {{box.data.end}} ⓘ</span></el-tooltip></article></div></template>
<style scoped>
.home-financial-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:18px 0}.financial-card{padding:18px;min-width:0;margin:0;display:flex;flex-direction:column}.financial-card header{display:flex;flex-direction:column;gap:10px;align-items:stretch;justify-content:flex-start;min-height:86px;margin-bottom:12px}.financial-card h2{font-size:18px;line-height:26px;margin:0}.financial-body{min-height:260px;flex:1}.primary-metrics,.profit-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 12px}.primary-metrics{padding:8px 0 20px}.primary-metrics span,.profit-grid span{font-size:13px;color:#7b8c83;cursor:help}.primary-metrics strong{display:block;margin-top:10px;font-size:25px;overflow-wrap:anywhere}.primary-metrics small{font-size:12px;font-weight:400;margin-left:4px}.profit-grid{border-top:1px solid #e7eeeb;padding-top:18px;row-gap:22px}.profit-grid strong{display:block;font-size:20px;margin-top:8px;overflow-wrap:anywhere}.estimate-mark{font-size:12px;margin-left:2px}.negative{color:#d26969}.range-caption{color:#8b9b92;font-size:11px;margin-top:14px;cursor:help}.composition-table{max-height:200px;overflow:auto}.composition-table table{width:100%;font-size:12px;border-collapse:collapse}.composition-table th{position:sticky;top:0;background:#f4f7f5;color:#81938a;text-align:left}.composition-table td,.composition-table th{padding:9px 5px}.composition-table td:not(:first-child),.composition-table th:not(:first-child){text-align:right;white-space:nowrap}.composition-table i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px}@media(max-width:1700px){.home-financial-cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:750px){.home-financial-cards{grid-template-columns:1fr}}
</style>
